import{_ as e,o as r,c as a,ag as d}from"./chunks/framework.DEqXEGcv.js";const p=JSON.parse('{"title":"Post-Launch Observation Playbook","description":"","frontmatter":{},"headers":[],"relativePath":"POST_LAUNCH_OBSERVATION_PLAYBOOK.md","filePath":"POST_LAUNCH_OBSERVATION_PLAYBOOK.md","lastUpdated":1771123879000}'),o={name:"POST_LAUNCH_OBSERVATION_PLAYBOOK.md"};function i(n,t,s,c,l,h){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="post-launch-observation-playbook" tabindex="-1">Post-Launch Observation Playbook <a class="header-anchor" href="#post-launch-observation-playbook" aria-label="Permalink to &quot;Post-Launch Observation Playbook&quot;">​</a></h1><p><strong>Scope:</strong> thegent orchestration platform<br><strong>Date:</strong> 2026-02-14<br><strong>Related:</strong> WP-6007, <code>docs/RUNBOOK.md</code> §4, <code>docs/enterprise/OPERATING_MODEL.md</code></p><hr><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>This playbook defines incident severity classification, escalation SLA mapping, and rollback capacity for post-launch observation. It complements the RUNBOOK and OPERATING_MODEL for launch readiness.</p><hr><h2 id="_2-incident-severity-classification" tabindex="-1">2. Incident Severity Classification <a class="header-anchor" href="#_2-incident-severity-classification" aria-label="Permalink to &quot;2. Incident Severity Classification&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Severity</th><th>Definition</th><th>Examples</th></tr></thead><tbody><tr><td><strong>P1 – Critical</strong></td><td>Production down; data loss/corruption; security breach</td><td>Run registry corrupted; policy bypass; audit chain broken</td></tr><tr><td><strong>P2 – High</strong></td><td>Major feature unavailable; significant degradation</td><td>All providers failing; DAG run blocked; drift &gt; 20%</td></tr><tr><td><strong>P3 – Medium</strong></td><td>Partial degradation; workaround available</td><td>Single provider down; fallback rate &gt; 30%; health gate failing</td></tr><tr><td><strong>P4 – Low</strong></td><td>Minor issue; no user impact</td><td>Cosmetic; non-critical telemetry gap</td></tr></tbody></table><hr><h2 id="_3-severity-→-sla-mapping" tabindex="-1">3. Severity → SLA Mapping <a class="header-anchor" href="#_3-severity-→-sla-mapping" aria-label="Permalink to &quot;3. Severity → SLA Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Severity</th><th>First Response</th><th>Resolution Target</th><th>Escalation</th></tr></thead><tbody><tr><td><strong>P1</strong></td><td>15 min</td><td>4 hours</td><td>Immediate: Tech Lead + Product Owner + Security</td></tr><tr><td><strong>P2</strong></td><td>30 min</td><td>8 hours</td><td>Tech Lead within 1 hr; Product Owner if &gt; 4 hr</td></tr><tr><td><strong>P3</strong></td><td>2 hours</td><td>24 hours</td><td>Tech Lead; Operator can resolve</td></tr><tr><td><strong>P4</strong></td><td>24 hours</td><td>Next sprint</td><td>Backlog</td></tr></tbody></table><hr><h2 id="_4-observation-cadence" tabindex="-1">4. Observation Cadence <a class="header-anchor" href="#_4-observation-cadence" aria-label="Permalink to &quot;4. Observation Cadence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cadence</th><th>Action</th><th>Owner</th></tr></thead><tbody><tr><td><strong>Daily</strong></td><td><code>thegent benchmark</code> — success rate &gt; 90%</td><td>Operator</td></tr><tr><td><strong>Daily</strong></td><td><code>thegent govern escalate list --past-sla</code></td><td>Operator</td></tr><tr><td><strong>Weekly</strong></td><td><code>thegent observe drift</code> — structural/semantic budget</td><td>Operator</td></tr><tr><td><strong>Weekly</strong></td><td><code>thegent govern sweep</code> — drift + past-SLA</td><td>Operator</td></tr><tr><td><strong>Weekly</strong></td><td><code>thegent archive</code> — prune old sessions</td><td>Operator</td></tr><tr><td><strong>Per DAG</strong></td><td><code>thegent closure-pack</code> at session end</td><td>Operator</td></tr><tr><td><strong>Pre-prod</strong></td><td>Rollback capacity checklist (below)</td><td>Tech Lead</td></tr></tbody></table><hr><h2 id="_5-rollback-capacity-checklist" tabindex="-1">5. Rollback Capacity Checklist <a class="header-anchor" href="#_5-rollback-capacity-checklist" aria-label="Permalink to &quot;5. Rollback Capacity Checklist&quot;">​</a></h2><p>Before production cutover, verify:</p><ul><li>[ ] <code>thegent dag checkpoints</code> returns at least one recent baseline</li><li>[ ] <code>thegent dag rollback &lt;checkpoint_id&gt;</code> tested in staging</li><li>[ ] Session data under <code>THGENT_RETENTION_DAYS_SESSIONS</code> (default 30d)</li><li>[ ] Override TTL understood (<code>THGENT_OVERRIDE_TTL_SECONDS</code> = 24h)</li><li>[ ] Escalation queue empty or all past-SLA items assigned</li><li>[ ] Trust boundary (WP-3007): no skip-level promotion without audit</li><li>[ ] Drift block (XC2): <code>thegent dag run --check-drift</code> blocks when drift exceeds budget</li></ul><hr><h2 id="_6-escalation-triggers" tabindex="-1">6. Escalation Triggers <a class="header-anchor" href="#_6-escalation-triggers" aria-label="Permalink to &quot;6. Escalation Triggers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trigger</th><th>Action</th></tr></thead><tbody><tr><td>Success rate &lt; 85% for 24h</td><td>P2; escalate to Tech Lead</td></tr><tr><td>Escalation queue &gt; 5 past-SLA</td><td>P2; escalate to Product Owner</td></tr><tr><td>Audit verify fails</td><td>P1; escalate to Security</td></tr><tr><td>Critical lane blocked by drift</td><td>P2; run <code>thegent observe drift</code>; remediate adapter</td></tr><tr><td>Circuit open for &gt; 1 hr</td><td>P3; investigate provider; consider failover</td></tr></tbody></table><hr><h2 id="_7-references" tabindex="-1">7. References <a class="header-anchor" href="#_7-references" aria-label="Permalink to &quot;7. References&quot;">​</a></h2><ul><li><code>docs/RUNBOOK.md</code> — Recovery, escalation, post-launch §4</li><li><code>docs/enterprise/OPERATING_MODEL.md</code> — RACI, escalation paths</li><li><code>docs/enterprise/DECOMMISSIONING_PLAN.md</code> — Rollback strategy</li></ul>',24)])])}const u=e(o,[["render",i]]);export{p as __pageData,u as default};
